pub fn parse_mf1_mt460(
    lines: &[String],
    read_opts: &ReadOpts,
    parse_opts: &ParseOpts,
) -> EndfResult<EndfValue> {
    let mut ofs: usize = 0;
    let mut result = EndfValue::new_dict();
    let mut var_awr: f64 = 0.0;
    let mut var_e: f64 = 0.0;
    let mut var_i: f64 = 0.0;
    let mut var_lambda: f64 = 0.0;
    let mut var_lo: f64 = 0.0;
    let mut var_ng: f64 = 0.0;
    let mut var_nnf: f64 = 0.0;
    let mut var_np: f64 = 0.0;
    let mut var_nr: f64 = 0.0;
    let mut var_t: f64 = 0.0;
    let mut var_table: f64 = 0.0;
    let mut var_tint: f64 = 0.0;
    let mut var_za: f64 = 0.0;

    if !lines.is_empty() {
        let ctrl = records::read_ctrl(&lines[0], read_opts)?;
        result.insert("MAT", EndfValue::Int(ctrl.mat as i64));
        result.insert("MF", EndfValue::Int(ctrl.mf as i64));
        result.insert("MT", EndfValue::Int(ctrl.mt as i64));
    }
    let lookahead_ok_0 = {
        let saved_ofs = ofs;
        let ok = (|| -> Result<bool, EndfError> {
            if ofs + 0 >= lines.len() { return Ok(false); }
            let (cont_0, _ctrl) = read_cont(&lines[ofs + 0], read_opts)?;
            var_za = cont_0.c1;
            var_awr = cont_0.c2;
            var_lo = cont_0.l1 as f64;
            var_ng = cont_0.n1 as f64;
            Ok((var_lo as f64 as i64) == (1_f64 as i64))
        })().unwrap_or(false);
        ok
    };
    let lookahead_ok_1 = {
        let saved_ofs = ofs;
        let ok = (|| -> Result<bool, EndfError> {
            if ofs + 0 >= lines.len() { return Ok(false); }
            let (cont_0, _ctrl) = read_cont(&lines[ofs + 0], read_opts)?;
            var_za = cont_0.c1;
            var_awr = cont_0.c2;
            var_lo = cont_0.l1 as f64;
            Ok((var_lo as f64 as i64) == (2_f64 as i64))
        })().unwrap_or(false);
        ok
    };
    if lookahead_ok_0 {
        // HEAD/CONT record
        {
            let (cont, _ctrl) = read_cont(lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?, read_opts)?;
            ofs += 1;
            var_za = cont.c1;
            result.insert("ZA", f64_to_endf_value(var_za));
            var_awr = cont.c2;
            result.insert("AWR", f64_to_endf_value(var_awr));
            var_lo = cont.l1 as f64;
            result.insert("LO", EndfValue::Int(var_lo as i64));
            // field l2 expected 0 (validation skipped in compiled mode)
            var_ng = cont.n1 as f64;
            result.insert("NG", EndfValue::Int(var_ng as i64));
            // field n2 expected 0 (validation skipped in compiled mode)
        }
        for var_i_loop_ in (1_f64 as i64)..=(var_ng as f64 as i64) {
            var_i = var_i_loop_ as f64;
            // TAB1 record
            {
                let line_refs: Vec<&str> = lines[ofs..].iter().map(|s| s.as_str()).collect();
                let (cont, body, _ctrl, consumed) = read_tab1(&line_refs, 0, read_opts)?;
                ofs += consumed;

                if !result.contains_key("E") {
                    result.insert("E", EndfValue::new_dict());
                }
                result.get_mut("E").unwrap().insert(EndfKey::Int(var_i as f64 as i64), f64_to_endf_value(cont.c1));
                // field c2 expected 0 (validation skipped in compiled mode)
                var_i = cont.l1 as f64;
                result.insert("i", EndfValue::Int(var_i as i64));
                // field l2 expected 0 (validation skipped in compiled mode)

                let mut tab_section = EndfValue::new_dict();
                tab_section.insert("NBT", list_from_i64(&body.nbt));
                tab_section.insert("INT", list_from_i64(&body.int));
                tab_section.insert("tint", list_from_f64(&body.x));
                tab_section.insert("T", list_from_f64(&body.y));
                if !result.contains_key("table") {
                    result.insert("table", EndfValue::new_dict());
                }
                result.get_mut("table").unwrap().insert(EndfKey::Int(var_i as f64 as i64), tab_section);
            }
        }
    } else if lookahead_ok_1 {
        // HEAD/CONT record
        {
            let (cont, _ctrl) = read_cont(lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?, read_opts)?;
            ofs += 1;
            var_za = cont.c1;
            result.insert("ZA", f64_to_endf_value(var_za));
            var_awr = cont.c2;
            result.insert("AWR", f64_to_endf_value(var_awr));
            var_lo = cont.l1 as f64;
            result.insert("LO", EndfValue::Int(var_lo as i64));
            // field l2 expected 0 (validation skipped in compiled mode)
            // field n1 expected 0 (validation skipped in compiled mode)
            // field n2 expected 0 (validation skipped in compiled mode)
        }
        // LIST record
        {
            let line_refs: Vec<&str> = lines[ofs..].iter().map(|s| s.as_str()).collect();
            let (cont, vals, _ctrl, consumed) = read_list(&line_refs, 0, read_opts)?;
            ofs += consumed;

            // field c1 expected 0 (validation skipped in compiled mode)
            // field c2 expected 0 (validation skipped in compiled mode)
            // field l1 expected 0 (validation skipped in compiled mode)
            // field l2 expected 0 (validation skipped in compiled mode)
            var_nnf = cont.n1 as f64;
            result.insert("NNF", EndfValue::Int(var_nnf as i64));
            // field n2 expected 0 (validation skipped in compiled mode)

            let mut vi: usize = 0;
            if (1_f64 as i64) <= (var_nnf as f64 as i64) {
                if !result.contains_key("lambda") { result.insert("lambda", EndfValue::new_dict()); }
            }
            for var_i_loop_ in (1_f64 as i64)..=(var_nnf as f64 as i64) {
                var_i = var_i_loop_ as f64;
                let _val = vals[vi];
                result.get_mut("lambda").unwrap().insert(EndfKey::Int(var_i as f64 as i64), EndfValue::Float(_val));
                vi += 1;
            }
        }
    }
    // SEND
    Ok(result)
}

pub fn write_mf1_mt460(
    data: &EndfValue,
    write_opts: &WriteOpts,
) -> EndfResult<Vec<String>> {
    let mut lines: Vec<String> = Vec::new();
    let ctrl = get_ctrl(data);
    if (get_float(data, "LO") as i64) == (1_f64 as i64) {
        // Write HEAD/CONT
        lines.push(write_cont(&ContRecord { c1: get_float(data, "ZA"), c2: get_float(data, "AWR"), l1: get_float(data, "LO") as i64, l2: 0_f64 as i64, n1: get_float(data, "NG") as i64, n2: 0_f64 as i64 }, &ctrl, write_opts));
        for _i_i in (1_f64 as i64)..=(get_float(data, "NG") as i64) {
            // Write TAB1
            let _tab_scope = &data.get("table").and_then(|d| d.get(EndfKey::Int(get_float(data, "i") as i64))).unwrap();
            let _nbt = get_int_vec(_tab_scope, "NBT");
            let _int = get_int_vec(_tab_scope, "INT");
            let _x = get_float_vec(_tab_scope, "tint");
            let _y = get_float_vec(_tab_scope, "T");
            let _nr = _nbt.len() as i64;
            let _np = _x.len() as i64;
            lines.push(write_cont(&ContRecord { c1: data.get("E").and_then(|d| d.get(EndfKey::Int(get_float(data, "i") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0), c2: 0_f64, l1: get_float(data, "i") as i64, l2: 0_f64 as i64, n1: _nr, n2: _np }, &ctrl, write_opts));
            let _body = Tab1Body { nbt: _nbt, int: _int, x: _x, y: _y };
            lines.extend(write_tab1_body(&_body, &ctrl, write_opts));
        }
    } else if (get_float(data, "LO") as i64) == (2_f64 as i64) {
        // Write HEAD/CONT
        lines.push(write_cont(&ContRecord { c1: get_float(data, "ZA"), c2: get_float(data, "AWR"), l1: get_float(data, "LO") as i64, l2: 0_f64 as i64, n1: 0_f64 as i64, n2: 0_f64 as i64 }, &ctrl, write_opts));
        // Write LIST
        let mut _vals: Vec<f64> = Vec::new();
        let _list_scope = &data;
        for _i_i in (1_f64 as i64)..=(get_float(data, "NNF") as i64) {
            _vals.push(_list_scope.get("lambda").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "i") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
        }
        lines.push(write_cont(&ContRecord { c1: 0_f64, c2: 0_f64, l1: 0_f64 as i64, l2: 0_f64 as i64, n1: _vals.len() as i64, n2: 0_f64 as i64 }, &ctrl, write_opts));
        lines.extend(records::write_endf_numbers(&_vals, &ctrl, false, write_opts));
    }
    // SEND
    Ok(lines)
}

