pub fn parse_mf7_mt451(
    lines: &[String],
    read_opts: &ReadOpts,
    parse_opts: &ParseOpts,
) -> EndfResult<EndfValue> {
    let mut ofs: usize = 0;
    let mut result = EndfValue::new_dict();
    let mut var_afi: f64 = 0.0;
    let mut var_awr: f64 = 0.0;
    let mut var_awri: f64 = 0.0;
    let mut var_i: f64 = 0.0;
    let mut var_j: f64 = 0.0;
    let mut var_lisi: f64 = 0.0;
    let mut var_na: f64 = 0.0;
    let mut var_nas: f64 = 0.0;
    let mut var_ni: f64 = 0.0;
    let mut var_sfi: f64 = 0.0;
    let mut var_za: f64 = 0.0;
    let mut var_zai: f64 = 0.0;

    if !lines.is_empty() {
        let ctrl = records::read_ctrl(&lines[0], read_opts)?;
        result.insert("MAT", EndfValue::Int(ctrl.mat as i64));
        result.insert("MF", EndfValue::Int(ctrl.mf as i64));
        result.insert("MT", EndfValue::Int(ctrl.mt as i64));
    }
    // HEAD/CONT record
    {
        let (cont, _ctrl) = read_cont(lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?, read_opts)?;
        ofs += 1;
        var_za = cont.c1;
        result.insert("ZA", f64_to_endf_value(var_za));
        var_awr = cont.c2;
        result.insert("AWR", f64_to_endf_value(var_awr));
        var_na = cont.l1 as f64;
        result.insert("NA", EndfValue::Int(var_na as i64));
        // field l2 expected 0 (validation skipped in compiled mode)
        // field n1 expected 0 (validation skipped in compiled mode)
        // field n2 expected 0 (validation skipped in compiled mode)
    }
    for var_i_loop_ in (1_f64 as i64)..=(var_na as f64 as i64) {
        var_i = var_i_loop_ as f64;
        // LIST record
        {
            let line_refs: Vec<&str> = lines[ofs..].iter().map(|s| s.as_str()).collect();
            let (cont, vals, _ctrl, consumed) = read_list(&line_refs, 0, read_opts)?;
            ofs += consumed;

            // field c1 expected 0 (validation skipped in compiled mode)
            // field c2 expected 0 (validation skipped in compiled mode)
            var_nas = cont.l1 as f64;
            result.insert("NAS", EndfValue::Int(var_nas as i64));
            // field l2 expected 0 (validation skipped in compiled mode)
            if !result.contains_key("NI") {
                result.insert("NI", EndfValue::new_dict());
            }
            result.get_mut("NI").unwrap().insert(EndfKey::Int(var_i as f64 as i64), EndfValue::Int(cont.n2 as i64));
            // field n1 complex expression (validation skipped in compiled mode)

            let mut vi: usize = 0;
            if (1_f64 as i64) <= (result.get("NI").and_then(|d| d.get(EndfKey::Int(var_i as f64 as i64))).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) {
                if !result.contains_key("ZAI") { result.insert("ZAI", EndfValue::new_dict()); }
                if !result.contains_key("LISI") { result.insert("LISI", EndfValue::new_dict()); }
                if !result.contains_key("AFI") { result.insert("AFI", EndfValue::new_dict()); }
                if !result.contains_key("AWRI") { result.insert("AWRI", EndfValue::new_dict()); }
                if !result.contains_key("SFI") { result.insert("SFI", EndfValue::new_dict()); }
            }
            for var_j_loop_ in (1_f64 as i64)..=(result.get("NI").and_then(|d| d.get(EndfKey::Int(var_i as f64 as i64))).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) {
                var_j = var_j_loop_ as f64;
                let _val = vals[vi];
                if !result.get_mut("ZAI").unwrap().contains_key(EndfKey::Int(var_i as f64 as i64).clone()) { result.get_mut("ZAI").unwrap().insert(EndfKey::Int(var_i as f64 as i64).clone(), EndfValue::new_dict()); }
                let _nav_0 = result.get_mut("ZAI").unwrap().get_mut(EndfKey::Int(var_i as f64 as i64)).unwrap();
                _nav_0.insert(EndfKey::Int(var_j as f64 as i64), EndfValue::Float(_val));
                vi += 1;
                let _val = vals[vi];
                if !result.get_mut("LISI").unwrap().contains_key(EndfKey::Int(var_i as f64 as i64).clone()) { result.get_mut("LISI").unwrap().insert(EndfKey::Int(var_i as f64 as i64).clone(), EndfValue::new_dict()); }
                let _nav_0 = result.get_mut("LISI").unwrap().get_mut(EndfKey::Int(var_i as f64 as i64)).unwrap();
                _nav_0.insert(EndfKey::Int(var_j as f64 as i64), EndfValue::Float(_val));
                vi += 1;
                let _val = vals[vi];
                if !result.get_mut("AFI").unwrap().contains_key(EndfKey::Int(var_i as f64 as i64).clone()) { result.get_mut("AFI").unwrap().insert(EndfKey::Int(var_i as f64 as i64).clone(), EndfValue::new_dict()); }
                let _nav_0 = result.get_mut("AFI").unwrap().get_mut(EndfKey::Int(var_i as f64 as i64)).unwrap();
                _nav_0.insert(EndfKey::Int(var_j as f64 as i64), EndfValue::Float(_val));
                vi += 1;
                let _val = vals[vi];
                if !result.get_mut("AWRI").unwrap().contains_key(EndfKey::Int(var_i as f64 as i64).clone()) { result.get_mut("AWRI").unwrap().insert(EndfKey::Int(var_i as f64 as i64).clone(), EndfValue::new_dict()); }
                let _nav_0 = result.get_mut("AWRI").unwrap().get_mut(EndfKey::Int(var_i as f64 as i64)).unwrap();
                _nav_0.insert(EndfKey::Int(var_j as f64 as i64), EndfValue::Float(_val));
                vi += 1;
                let _val = vals[vi];
                if !result.get_mut("SFI").unwrap().contains_key(EndfKey::Int(var_i as f64 as i64).clone()) { result.get_mut("SFI").unwrap().insert(EndfKey::Int(var_i as f64 as i64).clone(), EndfValue::new_dict()); }
                let _nav_0 = result.get_mut("SFI").unwrap().get_mut(EndfKey::Int(var_i as f64 as i64)).unwrap();
                _nav_0.insert(EndfKey::Int(var_j as f64 as i64), EndfValue::Float(_val));
                vi += 1;
                // list body constant 0 (validation skipped)
                vi += 1;
            }
        }
    }
    // SEND
    Ok(result)
}

pub fn write_mf7_mt451(
    data: &EndfValue,
    write_opts: &WriteOpts,
) -> EndfResult<Vec<String>> {
    let mut lines: Vec<String> = Vec::new();
    let ctrl = get_ctrl(data);
    // Write HEAD/CONT
    lines.push(write_cont(&ContRecord { c1: get_float(data, "ZA"), c2: get_float(data, "AWR"), l1: get_float(data, "NA") as i64, l2: 0_f64 as i64, n1: 0_f64 as i64, n2: 0_f64 as i64 }, &ctrl, write_opts));
    for _i_i in (1_f64 as i64)..=(get_float(data, "NA") as i64) {
        // Write LIST
        let mut _vals: Vec<f64> = Vec::new();
        let _list_scope = &data;
        for _i_j in (1_f64 as i64)..=(data.get("NI").and_then(|d| d.get(EndfKey::Int(get_float(data, "i") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) {
            _vals.push(_list_scope.get("ZAI").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "i") as i64))).and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "j") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
            _vals.push(_list_scope.get("LISI").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "i") as i64))).and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "j") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
            _vals.push(_list_scope.get("AFI").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "i") as i64))).and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "j") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
            _vals.push(_list_scope.get("AWRI").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "i") as i64))).and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "j") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
            _vals.push(_list_scope.get("SFI").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "i") as i64))).and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "j") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
            _vals.push(0_f64);
        }
        lines.push(write_cont(&ContRecord { c1: 0_f64, c2: 0_f64, l1: get_float(data, "NAS") as i64, l2: 0_f64 as i64, n1: _vals.len() as i64, n2: data.get("NI").and_then(|d| d.get(EndfKey::Int(get_float(data, "i") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0) as i64 }, &ctrl, write_opts));
        lines.extend(records::write_endf_numbers(&_vals, &ctrl, false, write_opts));
    }
    // SEND
    Ok(lines)
}

pub fn parse_mf8_wildcard(
    lines: &[String],
    read_opts: &ReadOpts,
    parse_opts: &ParseOpts,
) -> EndfResult<EndfValue> {
    let mut ofs: usize = 0;
    let mut result = EndfValue::new_dict();
    let mut var_awr: f64 = 0.0;
    let mut var_br: f64 = 0.0;
    let mut var_ct: f64 = 0.0;
    let mut var_elfs: f64 = 0.0;
    let mut var_end: f64 = 0.0;
    let mut var_hl: f64 = 0.0;
    let mut var_k: f64 = 0.0;
    let mut var_l: f64 = 0.0;
    let mut var_lfs: f64 = 0.0;
    let mut var_lis: f64 = 0.0;
    let mut var_liso: f64 = 0.0;
    let mut var_lmf: f64 = 0.0;
    let mut var_nd: f64 = 0.0;
    let mut var_no: f64 = 0.0;
    let mut var_ns: f64 = 0.0;
    let mut var_rtyp: f64 = 0.0;
    let mut var_subsection: f64 = 0.0;
    let mut var_za: f64 = 0.0;
    let mut var_zan: f64 = 0.0;
    let mut var_zap: f64 = 0.0;

    if !lines.is_empty() {
        let ctrl = records::read_ctrl(&lines[0], read_opts)?;
        result.insert("MAT", EndfValue::Int(ctrl.mat as i64));
        result.insert("MF", EndfValue::Int(ctrl.mf as i64));
        result.insert("MT", EndfValue::Int(ctrl.mt as i64));
    }
    // HEAD/CONT record
    {
        let (cont, _ctrl) = read_cont(lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?, read_opts)?;
        ofs += 1;
        var_za = cont.c1;
        result.insert("ZA", f64_to_endf_value(var_za));
        var_awr = cont.c2;
        result.insert("AWR", f64_to_endf_value(var_awr));
        var_lis = cont.l1 as f64;
        result.insert("LIS", EndfValue::Int(var_lis as i64));
        var_liso = cont.l2 as f64;
        result.insert("LISO", EndfValue::Int(var_liso as i64));
        var_ns = cont.n1 as f64;
        result.insert("NS", EndfValue::Int(var_ns as i64));
        var_no = cont.n2 as f64;
        result.insert("NO", EndfValue::Int(var_no as i64));
    }
    if (var_no as f64 as i64) == (0_f64 as i64) {
        for var_k_loop_ in (1_f64 as i64)..=(var_ns as f64 as i64) {
            var_k = var_k_loop_ as f64;
            // Section: subsection
            {
                let mut section_subsection = EndfValue::new_dict();
                std::mem::swap(&mut result, &mut section_subsection);
                // LIST record
                {
                    let line_refs: Vec<&str> = lines[ofs..].iter().map(|s| s.as_str()).collect();
                    let (cont, vals, _ctrl, consumed) = read_list(&line_refs, 0, read_opts)?;
                    ofs += consumed;

                    var_zap = cont.c1;
                    result.insert("ZAP", f64_to_endf_value(var_zap));
                    var_elfs = cont.c2;
                    result.insert("ELFS", f64_to_endf_value(var_elfs));
                    var_lmf = cont.l1 as f64;
                    result.insert("LMF", EndfValue::Int(var_lmf as i64));
                    var_lfs = cont.l2 as f64;
                    result.insert("LFS", EndfValue::Int(var_lfs as i64));
                    // field n2 expected 0 (validation skipped in compiled mode)
                    var_nd = (cont.n1 as f64 / (6_f64));
                    result.insert("ND", EndfValue::Int(var_nd as i64));

                    let mut vi: usize = 0;
                    if (1_f64 as i64) <= (var_nd as f64 as i64) {
                        if !result.contains_key("HL") { result.insert("HL", EndfValue::new_dict()); }
                        if !result.contains_key("RTYP") { result.insert("RTYP", EndfValue::new_dict()); }
                        if !result.contains_key("ZAN") { result.insert("ZAN", EndfValue::new_dict()); }
                        if !result.contains_key("BR") { result.insert("BR", EndfValue::new_dict()); }
                        if !result.contains_key("END") { result.insert("END", EndfValue::new_dict()); }
                        if !result.contains_key("CT") { result.insert("CT", EndfValue::new_dict()); }
                    }
                    for var_l_loop_ in (1_f64 as i64)..=(var_nd as f64 as i64) {
                        var_l = var_l_loop_ as f64;
                        let _val = vals[vi];
                        result.get_mut("HL").unwrap().insert(EndfKey::Int(var_l as f64 as i64), EndfValue::Float(_val));
                        vi += 1;
                        let _val = vals[vi];
                        result.get_mut("RTYP").unwrap().insert(EndfKey::Int(var_l as f64 as i64), EndfValue::Float(_val));
                        vi += 1;
                        let _val = vals[vi];
                        result.get_mut("ZAN").unwrap().insert(EndfKey::Int(var_l as f64 as i64), EndfValue::Float(_val));
                        vi += 1;
                        let _val = vals[vi];
                        result.get_mut("BR").unwrap().insert(EndfKey::Int(var_l as f64 as i64), EndfValue::Float(_val));
                        vi += 1;
                        let _val = vals[vi];
                        result.get_mut("END").unwrap().insert(EndfKey::Int(var_l as f64 as i64), EndfValue::Float(_val));
                        vi += 1;
                        let _val = vals[vi];
                        result.get_mut("CT").unwrap().insert(EndfKey::Int(var_l as f64 as i64), EndfValue::Float(_val));
                        vi += 1;
                    }
                }
                std::mem::swap(&mut result, &mut section_subsection);
                if !result.contains_key("subsection") {
                    result.insert("subsection", EndfValue::new_dict());
                }
                result.get_mut("subsection").unwrap().insert(EndfKey::Int(var_k as f64 as i64), section_subsection);
            }
        }
    } else if (var_no as f64 as i64) == (1_f64 as i64) {
        for var_k_loop_ in (1_f64 as i64)..=(var_ns as f64 as i64) {
            var_k = var_k_loop_ as f64;
            // Section: subsection
            {
                let mut section_subsection = EndfValue::new_dict();
                std::mem::swap(&mut result, &mut section_subsection);
                // HEAD/CONT record
                {
                    let (cont, _ctrl) = read_cont(lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?, read_opts)?;
                    ofs += 1;
                    var_zap = cont.c1;
                    result.insert("ZAP", f64_to_endf_value(var_zap));
                    var_elfs = cont.c2;
                    result.insert("ELFS", f64_to_endf_value(var_elfs));
                    var_lmf = cont.l1 as f64;
                    result.insert("LMF", EndfValue::Int(var_lmf as i64));
                    var_lfs = cont.l2 as f64;
                    result.insert("LFS", EndfValue::Int(var_lfs as i64));
                    // field n1 expected 0 (validation skipped in compiled mode)
                    // field n2 expected 0 (validation skipped in compiled mode)
                }
                std::mem::swap(&mut result, &mut section_subsection);
                if !result.contains_key("subsection") {
                    result.insert("subsection", EndfValue::new_dict());
                }
                result.get_mut("subsection").unwrap().insert(EndfKey::Int(var_k as f64 as i64), section_subsection);
            }
        }
    }
    // SEND
    Ok(result)
}

pub fn write_mf8_wildcard(
    data: &EndfValue,
    write_opts: &WriteOpts,
) -> EndfResult<Vec<String>> {
    let mut lines: Vec<String> = Vec::new();
    let ctrl = get_ctrl(data);
    // Write HEAD/CONT
    lines.push(write_cont(&ContRecord { c1: get_float(data, "ZA"), c2: get_float(data, "AWR"), l1: get_float(data, "LIS") as i64, l2: get_float(data, "LISO") as i64, n1: get_float(data, "NS") as i64, n2: get_float(data, "NO") as i64 }, &ctrl, write_opts));
    if (get_float(data, "NO") as i64) == (0_f64 as i64) {
        for _i_k in (1_f64 as i64)..=(get_float(data, "NS") as i64) {
            // Write section: subsection
            {
                let _saved_data = data;
                let data = data.get("subsection").and_then(|d| d.get(EndfKey::Int(get_float(data, "k") as i64))).unwrap();
                // Write LIST
                let mut _vals: Vec<f64> = Vec::new();
                let _list_scope = &data;
                for _i_l in (1_f64 as i64)..=(get_float(data, "ND") as i64) {
                    _vals.push(_list_scope.get("HL").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "l") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
                    _vals.push(_list_scope.get("RTYP").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "l") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
                    _vals.push(_list_scope.get("ZAN").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "l") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
                    _vals.push(_list_scope.get("BR").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "l") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
                    _vals.push(_list_scope.get("END").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "l") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
                    _vals.push(_list_scope.get("CT").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "l") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
                }
                lines.push(write_cont(&ContRecord { c1: get_float(data, "ZAP"), c2: get_float(data, "ELFS"), l1: get_float(data, "LMF") as i64, l2: get_float(data, "LFS") as i64, n1: _vals.len() as i64, n2: 0_f64 as i64 }, &ctrl, write_opts));
                lines.extend(records::write_endf_numbers(&_vals, &ctrl, false, write_opts));
                let data = _saved_data;
            }
        }
    } else if (get_float(data, "NO") as i64) == (1_f64 as i64) {
        for _i_k in (1_f64 as i64)..=(get_float(data, "NS") as i64) {
            // Write section: subsection
            {
                let _saved_data = data;
                let data = data.get("subsection").and_then(|d| d.get(EndfKey::Int(get_float(data, "k") as i64))).unwrap();
                // Write HEAD/CONT
                lines.push(write_cont(&ContRecord { c1: get_float(data, "ZAP"), c2: get_float(data, "ELFS"), l1: get_float(data, "LMF") as i64, l2: get_float(data, "LFS") as i64, n1: 0_f64 as i64, n2: 0_f64 as i64 }, &ctrl, write_opts));
                let data = _saved_data;
            }
        }
    }
    // SEND
    Ok(lines)
}

