pub fn parse_mf31_wildcard(
    lines: &[String],
    read_opts: &ReadOpts,
    parse_opts: &ParseOpts,
) -> EndfResult<EndfValue> {
    let mut ofs: usize = 0;
    let mut result = EndfValue::new_dict();
    let mut var_ci: f64 = 0.0;
    let mut var_k: f64 = 0.0;
    let mut var_lty: f64 = 0.0;
    let mut var_mats: f64 = 0.0;
    let mut var_mts: f64 = 0.0;
    let mut var_nci: f64 = 0.0;
    let mut var_weight: f64 = 0.0;
    let mut var_xlfss: f64 = 0.0;
    let mut var_xmfs: f64 = 0.0;
    let mut var_xmti: f64 = 0.0;

    if !lines.is_empty() {
        let ctrl = records::read_ctrl(&lines[0], read_opts)?;
        result.insert("MAT", EndfValue::Int(ctrl.mat as i64));
        result.insert("MF", EndfValue::Int(ctrl.mf as i64));
        result.insert("MT", EndfValue::Int(ctrl.mt as i64));
    }
    // HEAD/CONT record
    {
        let (cont, _ctrl) = read_cont(lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?, read_opts)?;
        ofs += 1;
        // field c1 expected 0 (validation skipped in compiled mode)
        // field c2 expected 0 (validation skipped in compiled mode)
        // field l1 expected 0 (validation skipped in compiled mode)
        var_lty = cont.l2 as f64;
        result.insert("LTY", EndfValue::Int(var_lty as i64));
        // field n1 expected 0 (validation skipped in compiled mode)
        // field n2 expected 0 (validation skipped in compiled mode)
    }
    if (var_lty as f64 as i64) == (0_f64 as i64) {
        // LIST record
        {
            let line_refs: Vec<&str> = lines[ofs..].iter().map(|s| s.as_str()).collect();
            let (cont, vals, _ctrl, consumed) = read_list(&line_refs, 0, read_opts)?;
            ofs += consumed;

            // field c1 expected 0 (validation skipped in compiled mode)
            // field c2 expected 0 (validation skipped in compiled mode)
            // field l1 expected 0 (validation skipped in compiled mode)
            // field l2 expected 0 (validation skipped in compiled mode)
            var_nci = cont.n2 as f64;
            result.insert("NCI", EndfValue::Int(var_nci as i64));
            // field n1 complex expression (validation skipped in compiled mode)

            let mut vi: usize = 0;
            if (1_f64 as i64) <= (var_nci as f64 as i64) {
                if !result.contains_key("CI") { result.insert("CI", EndfValue::new_dict()); }
                if !result.contains_key("XMTI") { result.insert("XMTI", EndfValue::new_dict()); }
            }
            for var_k_loop_ in (1_f64 as i64)..=(var_nci as f64 as i64) {
                var_k = var_k_loop_ as f64;
                let _val = vals[vi];
                result.get_mut("CI").unwrap().insert(EndfKey::Int(var_k as f64 as i64), EndfValue::Float(_val));
                vi += 1;
                let _val = vals[vi];
                result.get_mut("XMTI").unwrap().insert(EndfKey::Int(var_k as f64 as i64), EndfValue::Float(_val));
                vi += 1;
            }
        }
    } else if (((var_lty as f64 as i64) == (1_f64 as i64)) || ((var_lty as f64 as i64) == (2_f64 as i64))) || ((var_lty as f64 as i64) == (3_f64 as i64)) {
        // LIST record
        {
            let line_refs: Vec<&str> = lines[ofs..].iter().map(|s| s.as_str()).collect();
            let (cont, vals, _ctrl, consumed) = read_list(&line_refs, 0, read_opts)?;
            ofs += consumed;

            // field c1 expected 0 (validation skipped in compiled mode)
            // field c2 expected 0 (validation skipped in compiled mode)
            var_mats = cont.l1 as f64;
            result.insert("MATS", EndfValue::Int(var_mats as i64));
            var_mts = cont.l2 as f64;
            result.insert("MTS", EndfValue::Int(var_mts as i64));
            // field n1 expected 4 (validation skipped in compiled mode)
            // field n2 expected 1 (validation skipped in compiled mode)

            let mut vi: usize = 0;
            let _val = vals[vi];
            result.insert("XMFS", EndfValue::Float(_val));
            var_xmfs = _val;
            vi += 1;
            let _val = vals[vi];
            result.insert("XLFSS", EndfValue::Float(_val));
            var_xlfss = _val;
            vi += 1;
            // list body constant 0 (validation skipped)
            vi += 1;
            let _val = vals[vi];
            result.insert("Weight", EndfValue::Float(_val));
            var_weight = _val;
            vi += 1;
        }
    } else {
        return Err(EndfError::Stop { message: "The variable LTY contains an invalid value".to_string() });
    }
    // SEND
    Ok(result)
}

pub fn write_mf31_wildcard(
    data: &EndfValue,
    write_opts: &WriteOpts,
) -> EndfResult<Vec<String>> {
    let mut lines: Vec<String> = Vec::new();
    let ctrl = get_ctrl(data);
    // Write HEAD/CONT
    lines.push(write_cont(&ContRecord { c1: 0_f64, c2: 0_f64, l1: 0_f64 as i64, l2: get_float(data, "LTY") as i64, n1: 0_f64 as i64, n2: 0_f64 as i64 }, &ctrl, write_opts));
    if (get_float(data, "LTY") as i64) == (0_f64 as i64) {
        // Write LIST
        let mut _vals: Vec<f64> = Vec::new();
        let _list_scope = &data;
        for _i_k in (1_f64 as i64)..=(get_float(data, "NCI") as i64) {
            _vals.push(_list_scope.get("CI").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "k") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
            _vals.push(_list_scope.get("XMTI").and_then(|d| d.get(EndfKey::Int(get_float(_list_scope, "k") as i64))).and_then(|v| v.as_float()).unwrap_or(0.0));
        }
        lines.push(write_cont(&ContRecord { c1: 0_f64, c2: 0_f64, l1: 0_f64 as i64, l2: 0_f64 as i64, n1: _vals.len() as i64, n2: get_float(data, "NCI") as i64 }, &ctrl, write_opts));
        lines.extend(records::write_endf_numbers(&_vals, &ctrl, false, write_opts));
    } else if (((get_float(data, "LTY") as i64) == (1_f64 as i64)) || ((get_float(data, "LTY") as i64) == (2_f64 as i64))) || ((get_float(data, "LTY") as i64) == (3_f64 as i64)) {
        // Write LIST
        let mut _vals: Vec<f64> = Vec::new();
        let _list_scope = &data;
        _vals.push(get_float(_list_scope, "XMFS"));
        _vals.push(get_float(_list_scope, "XLFSS"));
        _vals.push(0_f64);
        _vals.push(get_float(_list_scope, "Weight"));
        lines.push(write_cont(&ContRecord { c1: 0_f64, c2: 0_f64, l1: get_float(data, "MATS") as i64, l2: get_float(data, "MTS") as i64, n1: _vals.len() as i64, n2: 1_f64 as i64 }, &ctrl, write_opts));
        lines.extend(records::write_endf_numbers(&_vals, &ctrl, false, write_opts));
    } else {
    }
    // SEND
    Ok(lines)
}

